package maps

import (
	"strings"
	"testing"
)

// Generated by hand from the frontend serializeGrid rules (index base36 + height base36).
const frontData = "01135a407589"

func TestSerializeCompatibleWithFrontend(t *testing.T) {
	g, err := Deserialize(Serialized{Width: 3, Depth: 2, Data: frontData})
	if err != nil {
		t.Fatal(err)
	}
	want := []Cell{{"floor", 1}, {"grass", 3}, {"stone", 10}, {"water", 0}, {"lava", 5}, {"ruin", 9}}
	for i, c := range want {
		if g.Cells[i] != c {
			t.Fatalf("cell %d = %+v, want %+v", i, g.Cells[i], c)
		}
	}
	if s := g.Serialize(); s.Data != frontData || s.Width != 3 || s.Depth != 2 {
		t.Fatalf("serialize = %+v", s)
	}
}

func TestDeserializeInvalid(t *testing.T) {
	for _, s := range []Serialized{
		{2, 2, "1111"}, {1, 1, "z1"}, {1, 1, "1!"}, {0, 1, ""}, {1, 1, "99"},
	} {
		if _, err := Deserialize(s); err == nil {
			t.Errorf("expected error for %+v", s)
		}
	}
}

func TestApplyPatch(t *testing.T) {
	cases := []struct {
		name    string
		cell    CellPatch
		wantErr string
	}{
		{"ok", CellPatch{1, 1, "sand", 4}, ""},
		{"out of bounds", CellPatch{5, 0, "sand", 1}, "fora do mapa"},
		{"negative", CellPatch{-1, 0, "sand", 1}, "fora do mapa"},
		{"unknown terrain", CellPatch{0, 0, "lego", 1}, "terreno desconhecido"},
		{"height high", CellPatch{0, 0, "sand", 11}, "altura inválida"},
		{"height low", CellPatch{0, 0, "sand", -1}, "altura inválida"},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			g, _ := NewGrid(3, 3)
			err := g.ApplyPatch(Patch{Cells: []CellPatch{c.cell}})
			if c.wantErr == "" {
				got, _ := g.At(1, 1)
				if err != nil || got != (Cell{"sand", 4}) {
					t.Fatalf("err=%v cell=%+v", err, got)
				}
				return
			}
			if err == nil || !strings.Contains(err.Error(), c.wantErr) {
				t.Fatalf("err = %v, want %q", err, c.wantErr)
			}
		})
	}
}

func TestApplyPatchIsAtomic(t *testing.T) {
	g, _ := NewGrid(2, 2)
	err := g.ApplyPatch(Patch{Cells: []CellPatch{{0, 0, "sand", 3}, {9, 9, "sand", 3}}})
	if c, _ := g.At(0, 0); err == nil || c.Terrain != "floor" {
		t.Fatal("patch must not partially apply")
	}
}
